/**
 * NiiViewer Component
 * 3D brain imaging viewer with NIfTI format support
 * Copied from src/components/NiiViewer.jsx
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import * as nifti from 'nifti-reader-js';
import { API_CONFIG } from '../../utils/constants';
import styles from './RightPanel.module.css';

const X_RIGHT_ON_SCREEN_RIGHT = true;
const MNI_BG_URL = 'static/mni_2mm.nii.gz';

function isStandardMNI2mm(dims, voxelMM) {
  const okDims = Array.isArray(dims) && dims[0] === 91 && dims[1] === 109 && dims[2] === 91;
  const okSp = voxelMM && Math.abs(voxelMM[0] - 2) < 1e-3 && Math.abs(voxelMM[1] - 2) < 1e-3 && Math.abs(voxelMM[2] - 2) < 1e-3;
  return okDims && okSp;
}

const MNI2MM = { x0: 90, y0: -126, z0: -72, vx: 2, vy: 2, vz: 2 };

export function NiiViewer({ query, searchSuccess = false }) {
  const [loadingBG, setLoadingBG] = useState(false);
  const [loadingMap, setLoadingMap] = useState(false);
  const [errBG, setErrBG] = useState('');
  const [errMap, setErrMap] = useState('');

  const [voxel] = useState(2.0);
  const [fwhm, setFwhm] = useState(10.0);
  const [kernel] = useState('gauss');
  const [r] = useState(6.0);

  const [overlayAlpha, setOverlayAlpha] = useState(0.5);
  const [posOnly] = useState(true);
  const [useAbs] = useState(false);
  const [thrMode, setThrMode] = useState('pctl');
  const [pctl, setPctl] = useState(95);
  const [thrValue, setThrValue] = useState(0);

  const bgRef = useRef(null);
  const mapRef = useRef(null);
  const getVoxelMM = () => {
    const vm = bgRef.current?.voxelMM ?? mapRef.current?.voxelMM ?? [1, 1, 1];
    return { x: vm[0], y: vm[1], z: vm[2] };
  };
  const [dims, setDims] = useState([0, 0, 0]);

  const [ix, setIx] = useState(0);
  const [iy, setIy] = useState(0);
  const [iz, setIz] = useState(0);

  const [cx, setCx] = useState('0');
  const [cy, setCy] = useState('0');
  const [cz, setCz] = useState('0');

  const canvases = [useRef(null), useRef(null), useRef(null)];

  const mapUrl = useMemo(() => {
    // 只在搜尋成功且有 query 時才構建 URL
    if (!query || !searchSuccess) return '';
    const u = new URL(`${API_CONFIG.BASE_URL}/query/${encodeURIComponent(query)}/nii`);
    u.searchParams.set('voxel', String(voxel));
    u.searchParams.set('fwhm', String(fwhm));
    u.searchParams.set('kernel', String(kernel));
    u.searchParams.set('r', String(r));
    return u.toString();
  }, [query, searchSuccess, voxel, fwhm, kernel, r]);

  function asTypedArray(header, buffer) {
    switch (header.datatypeCode) {
      case nifti.NIFTI1.TYPE_INT8:
        return new Int8Array(buffer);
      case nifti.NIFTI1.TYPE_UINT8:
        return new Uint8Array(buffer);
      case nifti.NIFTI1.TYPE_INT16:
        return new Int16Array(buffer);
      case nifti.NIFTI1.TYPE_UINT16:
        return new Uint16Array(buffer);
      case nifti.NIFTI1.TYPE_INT32:
        return new Int32Array(buffer);
      case nifti.NIFTI1.TYPE_UINT32:
        return new Uint32Array(buffer);
      case nifti.NIFTI1.TYPE_FLOAT32:
        return new Float32Array(buffer);
      case nifti.NIFTI1.TYPE_FLOAT64:
        return new Float64Array(buffer);
      default:
        return new Float32Array(buffer);
    }
  }

  function minmax(arr) {
    let mn = Infinity,
      mx = -Infinity;
    for (let i = 0; i < arr.length; i++) {
      const v = arr[i];
      if (v < mn) mn = v;
      if (v > mx) mx = v;
    }
    return [mn, mx];
  }

  function percentile(arr, p, step = Math.ceil(arr.length / 200000)) {
    if (!arr.length) return 0;
    const samp = [];
    for (let i = 0; i < arr.length; i += step) samp.push(arr[i]);
    samp.sort((a, b) => a - b);
    const k = Math.floor((p / 100) * (samp.length - 1));
    return samp[Math.max(0, Math.min(samp.length - 1, k))];
  }

  async function loadNifti(url) {
    const res = await fetch(url);
    if (!res.ok) {
      const t = await res.text().catch(() => '');
      throw new Error(`GET ${url} → ${res.status} ${t}`);
    }
    let ab = await res.arrayBuffer();
    if (nifti.isCompressed(ab)) ab = nifti.decompress(ab);
    if (!nifti.isNIFTI(ab)) throw new Error('not a NIfTI file');
    const header = nifti.readHeader(ab);
    const image = nifti.readImage(header, ab);
    const ta = asTypedArray(header, image);
    let f32;
    if (ta instanceof Float32Array) f32 = ta;
    else if (ta instanceof Float64Array) f32 = Float32Array.from(ta);
    else {
      const [mn, mx] = minmax(ta);
      const range = mx - mn || 1;
      f32 = new Float32Array(ta.length);
      for (let i = 0; i < ta.length; i++) f32[i] = (ta[i] - mn) / range;
    }
    const nx = header.dims[1] | 0;
    const ny = header.dims[2] | 0;
    const nz = header.dims[3] | 0;
    if (!nx || !ny || !nz) throw new Error('invalid dims');
    const [mn, mx] = minmax(f32);
    const vx = Math.abs(header.pixDims?.[1] ?? 1);
    const vy = Math.abs(header.pixDims?.[2] ?? 1);
    const vz = Math.abs(header.pixDims?.[3] ?? 1);
    return { data: f32, dims: [nx, ny, nz], voxelMM: [vx, vy, vz], min: mn, max: mx };
  }

  const idx2coord = (i, n, axis) => {
    const [nx, ny, nz] = dims;
    const { x: vx, y: vy, z: vz } = getVoxelMM();
    const isStd = isStandardMNI2mm([nx, ny, nz], [vx, vy, vz]);
    if (isStd) {
      if (axis === 'x') return -MNI2MM.vx * i + MNI2MM.x0;
      if (axis === 'y') return MNI2MM.vy * i + MNI2MM.y0;
      if (axis === 'z') return MNI2MM.vz * i + MNI2MM.z0;
    }
    const mmPerVoxel = axis === 'x' ? vx : axis === 'y' ? vy : vz;
    const AXIS_SIGN = { x: -1, y: 1, z: 1 };
    return AXIS_SIGN[axis] * (i - Math.floor(n / 2)) * mmPerVoxel;
  };

  const coord2idx = (c_mm, n, axis) => {
    const [nx, ny, nz] = dims;
    const { x: vx, y: vy, z: vz } = getVoxelMM();
    const isStd = isStandardMNI2mm([nx, ny, nz], [vx, vy, vz]);
    if (isStd) {
      let v;
      if (axis === 'x') v = (MNI2MM.x0 - c_mm) / MNI2MM.vx;
      else if (axis === 'y') v = (c_mm - MNI2MM.y0) / MNI2MM.vy;
      else v = (c_mm - MNI2MM.z0) / MNI2MM.vz;
      const idx = Math.round(v);
      return Math.max(0, Math.min(n - 1, idx));
    }
    const mmPerVoxel = axis === 'x' ? vx : axis === 'y' ? vy : vz;
    const AXIS_SIGN = { x: -1, y: 1, z: 1 };
    const sign = AXIS_SIGN[axis];
    const v = (sign * (c_mm / mmPerVoxel)) + Math.floor(n / 2);
    const idx = Math.round(v);
    return Math.max(0, Math.min(n - 1, idx));
  };

  useEffect(() => {
    let alive = true;
    setLoadingBG(true);
    setErrBG('');
    (async () => {
      try {
        const bg = await loadNifti(MNI_BG_URL);
        if (!alive) return;
        bgRef.current = bg;
        setDims(bg.dims);
        const [nx, ny, nz] = bg.dims;
        const mx = Math.floor(nx / 2),
          my = Math.floor(ny / 2),
          mz = Math.floor(nz / 2);
        setIx(mx);
        setIy(my);
        setIz(mz);
        setCx('0');
        setCy('0');
        setCz('0');
      } catch (e) {
        if (!alive) {
          bgRef.current = null;
          return;
        }
        setErrBG(e?.message || String(e));
        bgRef.current = null;
      } finally {
        if (alive) {
          setLoadingBG(false);
        }
      }
    })();
    return () => {
      alive = false;
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const mn = mapRef.current?.min ?? 0;
    const mx = mapRef.current?.max ?? 1;
    if (thrValue < mn || thrValue > mx) {
      setThrValue(Math.min(mx, Math.max(mn, thrValue)));
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mapRef.current, dims]);

  useEffect(() => {
    if (!mapUrl) {
      mapRef.current = null;
      return;
    }
    let alive = true;
    setLoadingMap(true);
    setErrMap('');
    (async () => {
      try {
        const mv = await loadNifti(mapUrl);
        if (!alive) return;
        mapRef.current = mv;
        if (!bgRef.current) {
          setDims(mv.dims);
          const [nx, ny, nz] = mv.dims;
          const mx = Math.floor(nx / 2),
            my = Math.floor(ny / 2),
            mz = Math.floor(nz / 2);
          setIx(mx);
          setIy(my);
          setIz(mz);
          setCx('0');
          setCy('0');
          setCz('0');
        }
      } catch (e) {
        if (!alive) {
          mapRef.current = null;
          return;
        }
        setErrMap(e?.message || String(e));
        mapRef.current = null;
      } finally {
        if (alive) {
          setLoadingMap(false);
        }
      }
    })();
    return () => {
      alive = false;
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mapUrl]);

  const mapThreshold = useMemo(() => {
    const mv = mapRef.current;
    if (!mv) return null;
    if (thrMode === 'value') return Number(thrValue) || 0;
    return percentile(mv.data, Math.max(0, Math.min(100, Number(pctl) || 95)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [thrMode, thrValue, pctl, mapRef.current]);

  function drawSlice(canvas, axis, index) {
    const [nx, ny, nz] = dims;
    const sx = (x) => (X_RIGHT_ON_SCREEN_RIGHT ? nx - 1 - x : x);
    const bg = bgRef.current;
    const map = mapRef.current;

    const dimsStr = dims.join('x');
    const bgOK = !!(bg && bg.dims.join('x') === dimsStr);
    const mapOK = !!(map && map.dims.join('x') === dimsStr);

    let w = 0,
      h = 0,
      getBG = null,
      getMap = null;
    if (axis === 'z') {
      w = nx;
      h = ny;
      if (bgOK) getBG = (x, y) => bg.data[sx(x) + y * nx + index * nx * ny];
      if (mapOK) getMap = (x, y) => map.data[sx(x) + y * nx + index * nx * ny];
    }
    if (axis === 'y') {
      w = nx;
      h = nz;
      if (bgOK) getBG = (x, y) => bg.data[sx(x) + index * nx + y * nx * ny];
      if (mapOK) getMap = (x, y) => map.data[sx(x) + index * nx + y * nx * ny];
    }
    if (axis === 'x') {
      w = ny;
      h = nz;
      if (bgOK) getBG = (x, y) => bg.data[index + x * nx + y * nx * ny];
      if (mapOK) getMap = (x, y) => map.data[index + x * nx + y * nx * ny];
    }

    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d', { willReadFrequently: false });
    const img = ctx.createImageData(w, h);

    const alpha = Math.max(0, Math.min(1, overlayAlpha));
    const R = 255,
      G = 0,
      B = 0;
    const thr = mapThreshold;

    const bgMin = bg?.min ?? 0;
    const bgMax = bg?.max ?? 1;
    const bgRange = bgMax - bgMin || 1;

    let p = 0;
    for (let yy = 0; yy < h; yy++) {
      const srcY = h - 1 - yy;
      for (let xx = 0; xx < w; xx++) {
        let gray = 0;
        if (getBG) {
          const vbg = getBG(xx, srcY);
          let g = (vbg - bgMin) / bgRange;
          if (g < 0) g = 0;
          if (g > 1) g = 1;
          gray = (g * 255) | 0;
        }
        img.data[p] = gray;
        img.data[p + 1] = gray;
        img.data[p + 2] = gray;
        img.data[p + 3] = 255;

        if (getMap) {
          let mv = getMap(xx, srcY);
          const raw = mv;
          if (useAbs) mv = Math.abs(mv);
          let pass = thr == null ? mv > 0 : mv >= thr;
          if (posOnly && raw <= 0) pass = false;
          if (pass) {
            img.data[p] = ((1 - alpha) * img.data[p] + alpha * R) | 0;
            img.data[p + 1] = ((1 - alpha) * img.data[p + 1] + alpha * G) | 0;
            img.data[p + 2] = ((1 - alpha) * img.data[p + 2] + alpha * B) | 0;
          }
        }
        p += 4;
      }
    }
    ctx.putImageData(img, 0, 0);

    ctx.save();
    ctx.strokeStyle = '#40E0D0';  // Tiffany Primary
    ctx.lineWidth = 2;
    let cx = 0,
      cy = 0;
    if (axis === 'z') {
      cx = Math.max(0, Math.min(w - 1, X_RIGHT_ON_SCREEN_RIGHT ? w - 1 - ix : ix));
      cy = Math.max(0, Math.min(h - 1, iy));
    } else if (axis === 'y') {
      cx = Math.max(0, Math.min(w - 1, X_RIGHT_ON_SCREEN_RIGHT ? w - 1 - ix : ix));
      cy = Math.max(0, Math.min(h - 1, iz));
    } else {
      cx = Math.max(0, Math.min(w - 1, iy));
      cy = Math.max(0, Math.min(h - 1, iz));
    }
    const screenY = h - 1 - cy;
    ctx.beginPath();
    ctx.moveTo(cx + 0.5, 0);
    ctx.lineTo(cx + 0.5, h);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, screenY + 0.5);
    ctx.lineTo(w, screenY + 0.5);
    ctx.stroke();
    ctx.restore();
  }

  function onCanvasClick(e, axis) {
    const canvas = e.currentTarget;
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) * (canvas.width / rect.width));
    const y = Math.floor((e.clientY - rect.top) * (canvas.height / rect.height));
    const srcY = canvas.height - 1 - y;
    const [nx, ny, nz] = dims;

    const toIdxX = (screenX) => (X_RIGHT_ON_SCREEN_RIGHT ? nx - 1 - screenX : screenX);
    if (axis === 'z') {
      const xi = toIdxX(x);
      setIx(xi);
      setIy(srcY);
      setCx(String(idx2coord(xi, nx, 'x')));
      setCy(String(idx2coord(srcY, ny, 'y')));
    } else if (axis === 'y') {
      const xi = toIdxX(x);
      setIx(xi);
      setIz(srcY);
      setCx(String(idx2coord(xi, nx, 'x')));
      setCz(String(idx2coord(srcY, nz, 'z')));
    } else {
      setIy(x);
      setIz(srcY);
      setCy(String(idx2coord(x, ny, 'y')));
      setCz(String(idx2coord(srcY, nz, 'z')));
    }
  }

  useEffect(() => {
    const [nx, ny, nz] = dims;
    if (!nx) return;
    setCx(String(idx2coord(ix, nx, 'x')));
    setCy(String(idx2coord(iy, ny, 'y')));
    setCz(String(idx2coord(iz, nz, 'z')));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ix, iy, iz, dims]);

  const commitCoord = (axis) => {
    const [nx, ny, nz] = dims;
    let vStr = axis === 'x' ? cx : axis === 'y' ? cy : cz;
    if (vStr === '' || vStr === '-') return;
    const parsed = parseFloat(vStr);
    if (Number.isNaN(parsed)) return;
    if (axis === 'x') setIx(coord2idx(parsed, nx, 'x'));
    if (axis === 'y') setIy(coord2idx(parsed, ny, 'y'));
    if (axis === 'z') setIz(coord2idx(parsed, nz, 'z'));
  };

  useEffect(() => {
    const [nx, ny, nz] = dims;
    if (!nx) return;
    const c0 = canvases[0].current,
      c1 = canvases[1].current,
      c2 = canvases[2].current;
    if (c0 && iz >= 0 && iz < nz) drawSlice(c0, 'z', iz);
    if (c1 && iy >= 0 && iy < ny) drawSlice(c1, 'y', iy);
    if (c2 && ix >= 0 && ix < nx) drawSlice(c2, 'x', ix);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dims, ix, iy, iz, overlayAlpha, posOnly, useAbs, thrMode, pctl, thrValue, loadingBG, loadingMap, errBG, errMap, query]);

  const [nx, ny, nz] = dims;

  const sliceConfigs = [
    { key: 'y', name: 'Coronal', axisLabel: 'Y', index: iy, setIndex: setIy, max: Math.max(0, ny - 1), canvasRef: canvases[1] },
    { key: 'x', name: 'Sagittal', axisLabel: 'X', index: ix, setIndex: setIx, max: Math.max(0, nx - 1), canvasRef: canvases[2] },
    { key: 'z', name: 'Axial', axisLabel: 'Z', index: iz, setIndex: setIz, max: Math.max(0, nz - 1), canvasRef: canvases[0] },
  ];

  return (
    <div className={styles.niiViewerContainer}>
      <div className={styles.niiViewerHeader}>
        <h3 className={styles.viewerTitle}>NIfTI Viewer</h3>
        {query && searchSuccess && (
          <a
            href={mapUrl}
            download={query ? `brain_map_${query.replace(/\s+/g, '_')}.nii.gz` : 'brain_map.nii.gz'}
            className={styles.downloadButtonLink}
            title="Download NIfTI brain map"
          >
            Download Map
          </a>
        )}
      </div>

      <div className={styles.controlsPanel}>
        <label className={styles.controlLabel}>
          <span>Threshold mode</span>
          <select value={thrMode} onChange={(e) => setThrMode(e.target.value)} className={styles.controlSelect}>
            <option value="value">Value</option>
            <option value="pctl">Percentile</option>
          </select>
        </label>

        {thrMode === 'value' ? (
          <label className={styles.controlLabel}>
            <span>Threshold</span>
            <input type="number" step="0.01" value={thrValue} onChange={(e) => setThrValue(Number(e.target.value))} className={styles.controlInput} />
          </label>
        ) : (
          <label className={styles.controlLabel}>
            <span>Percentile</span>
            <input type="number" min="50" max="99.9" step="0.5" value={pctl} onChange={(e) => setPctl(Number(e.target.value) || 95)} className={styles.controlInput} />
          </label>
        )}

        <div className={styles.coordinateInputs}>
          <label className={styles.coordLabel}>
            <span>X (mm):</span>
            <input
              type="text"
              inputMode="decimal"
              pattern="-?[0-9]*([.][0-9]+)?"
              className={styles.coordInput}
              value={cx}
              onChange={(e) => setCx(e.target.value)}
              onBlur={() => commitCoord('x')}
              onKeyDown={(e) => {
                if (e.key === 'Enter') commitCoord('x');
              }}
              aria-label="X coordinate"
            />
          </label>
          <label className={styles.coordLabel}>
            <span>Y (mm):</span>
            <input
              type="text"
              inputMode="decimal"
              pattern="-?[0-9]*([.][0-9]+)?"
              className={styles.coordInput}
              value={cy}
              onChange={(e) => setCy(e.target.value)}
              onBlur={() => commitCoord('y')}
              onKeyDown={(e) => {
                if (e.key === 'Enter') commitCoord('y');
              }}
              aria-label="Y coordinate"
            />
          </label>
          <label className={styles.coordLabel}>
            <span>Z (mm):</span>
            <input
              type="text"
              inputMode="decimal"
              pattern="-?[0-9]*([.][0-9]+)?"
              className={styles.coordInput}
              value={cz}
              onChange={(e) => setCz(e.target.value)}
              onBlur={() => commitCoord('z')}
              onKeyDown={(e) => {
                if (e.key === 'Enter') commitCoord('z');
              }}
              aria-label="Z coordinate"
            />
          </label>
        </div>
      </div>

      {(loadingBG || loadingMap) && <div className={styles.loadingIndicator}>Loading...</div>}
      {(errBG || errMap) && (
        <div className={styles.errorMessage}>
          No map found
        </div>
      )}

      {!!nx && (
        <div className={styles.slicesGrid}>
          {sliceConfigs.map(({ key, name, axisLabel, canvasRef }) => (
            <div key={key} className={styles.sliceContainer}>
              <div className={styles.sliceLabel}>
                {name} ({axisLabel})
              </div>
              <canvas
                ref={canvasRef}
                className={styles.sliceCanvas}
                onClick={(e) => onCanvasClick(e, key)}
                style={{ cursor: 'crosshair' }}
              />
            </div>
          ))}
        </div>
      )}

      <div className={styles.controlsPanel}>
        <label className={styles.controlLabel}>
          <span>Gaussian FWHM:</span>
          <input type="number" step="0.5" value={fwhm} onChange={(e) => setFwhm(Number(e.target.value) || 0)} className={styles.controlInput} />
        </label>
      </div>

      <div className={styles.controlsPanel}>
        <label className={styles.controlLabel}>
          <span>Overlay alpha</span>
          <input type="range" min="0" max="1" step="0.05" value={overlayAlpha} onChange={(e) => setOverlayAlpha(Number(e.target.value))} className={styles.rangeInput} />
        </label>
      </div>
    </div>
  );
}

