  const addToast = useCallback((message, options = {}) => {
    const {
      type = 'info',        // success | error | info | warning
      duration = 3000,      // Auto-dismiss duration (ms), 0 = no auto-dismiss
      action = null,        // Optional action button { label, onClick }
    } = options;

